#!/usr/bin/env python3
"""Regenerates the test FakeCore from the generated FltsCoreInterface.
Run after the core API changes: android/scripts/gen-fake-core.py"""

import re
from pathlib import Path

root = Path(__file__).resolve().parent.parent
source = (root / "app/src/main/java/uniffi/flts_ffi/flts_ffi.kt").read_text()
body = re.search(
    r"^public interface FltsCoreInterface \{(.*?)^\}", source, re.S | re.M
).group(1)

out = [
    "// Generated by scripts/gen-fake-core.py; do not edit.",
    "package com.TS.FLTS",
    "",
    "import java.util.Collections",
    "import uniffi.flts_ffi.*",
    "",
    "/// Each method runs its handler if a test set one, else throws.",
    "class FakeCore : FltsCoreInterface {",
    "    val calls: MutableList<String> = Collections.synchronizedList(mutableListOf())",
    "    fun count(name: String): Int = calls.count { it == name }",
    '    private fun notFaked(name: String): Nothing = throw CoreException.Failed("not faked: $name")',
]
pattern = re.compile(r"^\s*(suspend )?fun `(\w+)`\((.*?)\)(?:: (.+))?$", re.M)
for suspend, name, params, ret in pattern.findall(body):
    args = [p.strip() for p in params.split(", `")] if params.strip() else []
    names, types = [], []
    for arg in args:
        n, t = arg.lstrip("`").split("`: ", 1)
        names.append(n)
        types.append(t)
    ret = ret or "Unit"
    # In test code `Number` would be Kotlin's own; name the aliased types.
    plain = lambda t: re.sub(
        r"\bNumber\b",
        "Int",
        re.sub(r"\bUuid\b", "java.util.UUID", t.replace("kotlin.", "")),
    )
    types = [plain(t) for t in types]
    ret = plain(ret)
    prefix = "suspend " if suspend else ""
    out += [
        "",
        f"    var {name}Handler: ({prefix}({', '.join(types)}) -> {ret})? = null",
        f"    override {prefix}fun {name}({', '.join(f'{n}: {t}' for n, t in zip(names, types))}): {ret} {{",
        f'        calls.add("{name}")',
        f'        return ({name}Handler ?: notFaked("{name}"))({", ".join(names)})',
        "    }",
    ]
out += ["}", ""]
target = root / "app/src/test/java/com/TS/FLTS/FakeCore.kt"
target.parent.mkdir(parents=True, exist_ok=True)
target.write_text("\n".join(out))
print(f"wrote {target}")
